function onFault() {
  if (!_engine) return;
  /* Faults create turbulence at a random attractor position */
  _engine.field.entropy = Math.min(0.85, _engine.field.entropy + 0.12);
  _engine.injectStress(
    (Math.random() - 0.5) * BOUND * 1.5,
    (Math.random() - 0.5) * BOUND * 1.5,
    0, 400, 5
  );
}
